steps.script:
SettingsService.auto_allocate_wounds = true
var cg = GameState.state.units["U_CUSTODIAN_GUARD_C"]
cg.meta.stats["toughness"] = 3
cg.meta.stats["save"] = 7
cg.meta.stats["invuln"] = 0
for m in cg.models:
	m["invuln"] = 0
AIPlayer.enabled = true
AIPlayer.ai_players = {1: false, 2: true}
return AIPlayer.is_ai_player(2) and not AIPlayer.is_ai_player(1)

var out = []
for t in ToastManager.active_toasts:
	if is_instance_valid(t):
		for c in t.find_children("*", "Label", true, false):
			out.append(c.text)
var all = " | ".join(out)
return all.contains("FIRE OVERWATCH:") and all.contains("snap-shot")

for e in AIPlayer.get_action_log():
	if str(e.get("action_type", "")) == "USE_WINDOW_STRATAGEM" and str(e.get("stratagem_id", "")) == "fire_overwatch_11e":
		return true
return false

AIPlayer.enabled = false
AIPlayer.ai_players = {1: false, 2: false}
return true
